import raw from "./generated/er-guide.json";
import { erInscriptions } from "./er-reference";
import type { GuideCategory } from "./guide-types";

/**
 * The Elden Ring knowledge base: the game's own tutorial pages (with their illustrations)
 * plus the loading-screen knowledge cards, grouped by the game's own msgId bands — including
 * the official Status Effects explanations (Poison, Scarlet Rot, Blood Loss, Frostbite,
 * Sleep, Madness, Death Blight). Generated by data/src/build-er-guide.mjs; no wiki text.
 *
 * The war-monument inscriptions ride along as a final category. They are the same kind of
 * thing — in-world text the game shows you and then never lets you re-read — but they carry
 * no coordinates in the data, so they're an archive to read, not pins on a map. Inventing
 * positions for them would be a lie; leaving them out would waste them.
 */
const guideCategories = (raw as { categories: GuideCategory[] }).categories;

/** Inscription kinds → the guide category they read under. Kinds the build doesn't set
 *  (older artifacts) fall into the general inscriptions category. */
const INSCRIPTION_CATS: { id: string; label: string; kinds: string[] }[] = [
  { id: "monuments", label: "War Monuments", kinds: ["monument"] },
  { id: "riddles", label: "Seal Riddles", kinds: ["riddle"] },
  { id: "inscriptions", label: "Inscriptions", kinds: ["cross", "grave", "world"] },
];

const inscriptionCategories: GuideCategory[] = INSCRIPTION_CATS.flatMap(({ id, label, kinds }) => {
  const entries = erInscriptions
    .filter((i) => (i.kind ? kinds.includes(i.kind) : id === "inscriptions"))
    .map((i) => ({ id: i.id, title: i.title ?? i.text, body: i.title ? i.text : "" }));
  return entries.length ? [{ id, label, entries }] : [];
});

export const erGuideCategories: GuideCategory[] = [...guideCategories, ...inscriptionCategories];

/**
 * The combat panel names status effects the way NpcParam does ("Bleed", "Scarlet Rot"); the
 * game's own knowledge cards use the player-facing wording ("Status: Blood Loss"). This maps
 * one to the other by the card's stable msgId, so a boss's status row can carry the official
 * explanation of what the ailment actually does — no hand-written copy.
 */
const STATUS_CARD_ID: Record<string, number> = {
  Poison: 70,
  "Scarlet Rot": 71,
  Bleed: 72,
  Frostbite: 73,
  Sleep: 74,
  Madness: 75,
  Death: 76,
};

const statusCards = new Map(
  (erGuideCategories.find((c) => c.id === "status")?.entries ?? []).map((e) => [e.id, e]),
);

/** The game's official explanation of a status ailment, or undefined if it has no card. */
export const erStatusExplanation = (type: string): string | undefined =>
  statusCards.get(STATUS_CARD_ID[type])?.body;
